mapper.update:
UPDATE ADMIN_MST
SET LAST_CNTN_DT = NOW()
WHERE USER_ID = #{id}

mapper.select:
SELECT Q.CNTN_QSTN_SN, Q.CNTN_SN, Q.QSTN_TYPE_CD, CASE Q.QSTN_TYPE_CD WHEN 'SELECT' THEN '선택형 활동' WHEN 'DATA' THEN '데이터 입력' WHEN 'PHOTO' THEN '사진 업로드' WHEN 'SENTENCE' THEN '문장완성형' ELSE Q.QSTN_TYPE_CD END AS QSTN_TYPE_NM, Q.QSTN_NM, Q.QSTN_IMG_ATCH_FILE_ID, Q.OPTN_CN, Q.SORT_SEQ FROM EDU_CNTN_QSTN Q WHERE Q.CNTN_SN IN
#{contentId}
ORDER BY Q.CNTN_SN ASC, Q.SORT_SEQ ASC, Q.CNTN_QSTN_SN ASC

SELECT
	M.QSTNR_SN,
	M.QSTNR_TYPE_CD,
	M.EVL_SE_CD,
	M.QSTNR_NM
FROM EDU_QSTNR_MST M
WHERE M.QSTNR_SN = #{qstnrSn}
AND M.QSTNR_TYPE_CD = #{qstnrTypeCd}

	AND M.EVL_SE_CD = #{evlSeCd}

AND M.DEL_DT IS NULL

SELECT B.PST_SN, B.ETC2 AS DATA_TYPE_CD, B.LNKG_URL_ADDR AS LINK_URL, B.ETC5 AS VIDEO_EMBED_URL, B.ATCH_FILE_MNG_NO, F.FILE_SEQ, F.ATCH_FILE_PATH_NM AS FILE_URL, F.ORGNL_FILE_NM FROM BBS_ARTICLE B LEFT JOIN ATCH_FILE_INFO F ON F.ATCH_FILE_MNG_NO = B.ATCH_FILE_MNG_NO WHERE B.BBS_ID = 'LRNSUP' AND B.USE_YN = 'Y' AND B.PST_SN = #{pstSn}
AND F.FILE_SEQ = #{fileSeq}
AND F.FILE_SEQ IS NULL
LIMIT 1

mapper.insert:
INSERT INTO EDU_LRN_MTRL_DWNLD_LOG (
	PST_SN, ATCH_FILE_MNG_NO, FILE_SEQ, DATA_TYPE_CD, DWNLD_DT, RGTR_NM
) VALUES (
	#{pstSn}, NULLIF(#{atchFileMngNo}, ''), #{fileSeq}, #{dataTypeCd}, NOW(), 'tablet'
)

mapper.select:
SELECT DISTINCT M.MSG_SN, M.RSVT_SN, M.TRGT_NM AS TARGET_NM, M.STDNT_CNT AS STUDENT_COUNT, M.MSG_CN AS MESSAGE_CN, DATE_FORMAT(M.REG_DT, '%Y-%m-%d %H:%i:%s') AS REG_DT FROM EDU_TCHR_MSG M INNER JOIN EDU_TCHR_MSG_RCPT R ON R.MSG_SN = M.MSG_SN WHERE M.RSVT_SN = #{rsvtSn} AND R.STDNT_SN IN
#{studentSn}
AND R.READ_YN = 'N' AND M.DEL_DT IS NULL AND R.DEL_DT IS NULL ORDER BY M.REG_DT ASC, M.MSG_SN ASC

mapper.insert:
INSERT INTO EDU_TCHR_MSG (
	RSVT_SN, TRGT_NM, STDNT_CNT, MSG_CN, RGTR_NM, REG_DT
) VALUES (
	#{rsvtSn}, #{targetNm}, #{studentCount}, #{messageCn}, 'tablet', NOW()
)

mapper.update:
UPDATE EDU_TCHR_MSG_RCPT SET READ_YN = 'Y', READ_DT = COALESCE(READ_DT, NOW()), MDFR_NM = 'tablet', MDFCN_DT = NOW() WHERE MSG_SN = #{msgSn} AND STDNT_SN IN
#{studentSn}
AND DEL_DT IS NULL

UPDATE EDU_RSVT_STDNT SET ATND_YN = CASE WHEN STDNT_SN IN
#{studentSn}
THEN 'Y' ELSE 'N' END, MDFCN_DT = NOW(), MDFR_NM = 'tablet' WHERE RSVT_SN = #{rsvtSn} AND DEL_DT IS NULL

UPDATE EDU_LRN_ANS
SET DEL_DT = NOW(),
	DLTR_NM = 'tablet'
WHERE RSVT_SN = #{rsvtSn}
AND STDNT_SN = #{stdntSn}
AND ANS_TYPE_CD = 'WORKSHEET'
AND STEP_CD = #{stepCd}
AND DEL_DT IS NULL

UPDATE EDU_LRN_ANS
SET DEL_DT = NOW(),
	DLTR_NM = 'tablet'
WHERE RSVT_SN = #{rsvtSn}
AND STDNT_SN = #{stdntSn}
AND ANS_TYPE_CD = #{ansTypeCd}
AND DEL_DT IS NULL

UPDATE EDU_LRN_PRGRS_LOG
SET ACTVT_NM = #{actvtNm},
	STEP_STTS_CD = 'DONE',
	CMPTN_DT = NOW(),
	MDFR_NM = 'tablet',
	MDFCN_DT = NOW()
WHERE RSVT_SN = #{rsvtSn}
AND STDNT_SN = #{stdntSn}
AND STEP_CD = #{stepCd}

UPDATE EDU_PUSH_DVC
SET ACTV_YN = 'N',
	LAST_UPDT_DT = NOW()
WHERE FCM_TKN = #{fcmToken}
AND DVC_ID != #{deviceId}
AND ACTV_YN = 'Y'
